                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == foreground and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        q.append((nr,nc))
            comps.append(sorted(cells))
