            for a, b in zip(sr, tr):
                for c in range(common, w):
                    if grid[a][c] == foreground and grid[b][c] == background:
                        out[b][c] = 1
            copied.add(j)
            break

    for ci, cells in enumerate(comps):
        if ci in copied:
            continue
        rows = sorted({r for r,c in cells})
        positions = {r: [c for c in range(w) if grid[r][c] == foreground] for r in rows}
        rightmost = {r: max(positions[r]) for r in rows}
        runs = {}
        terminal = {}
        for r in rows:
            ps = positions[r]
            best = cur = 0
            prev = -2
            for c in ps:
                cur = cur + 1 if c == prev + 1 else 1
                best = max(best, cur)
                prev = c
            runs[r] = best
            terminal[r] = cur

        # Detect exact repeated suffix motifs (including one or more trailing background cells).
        periodic = {}
        for r in rows:
            m = rightmost[r]
            bits = [grid[r][c] == foreground for c in range(w)]
            candidates = []
            for period in range(2, min(8, w // 2) + 1):
